<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class automatic extends lib { var $cron_cache = 'qqworld-collector-static-cache-cron-terms-cache'; var $abspath; public function init() { if (!$this->options->qc_static_cache_enabled) return; add_action( 'wp_insert_post', array($this, 'wp_insert_post'), 99999, 3 ); add_action( 'wp_insert_comment', array($this, 'refresh_post_when_update_comment') ); add_action( 'edit_comment', array($this, 'refresh_post_when_update_comment') ); add_action( $this->core->refreash_action, array($this, 'refreash_action') ); } public function add_bulk_actions($actions) { print_r($actions); $actions['update-cache'] = __('Update Cache', $this->text_domain); $actions['remove-cache'] = __('Remove Cache', $this->text_domain); return $actions; } public function refresh_post_when_update_comment($comment_id) { $comment = get_comment($comment_id); $post_id = $comment->comment_post_ID; $post_type = get_post_type($post_id); if (!in_array($post_type, $this->options->qc_static_cache_post_types)) return; $this->core->singular->make_cache($post_id, $post_type); } public function wp_insert_post($post_ID, $post, $update) { if ($post->post_status != 'publish') return; if (!in_array($post->post_type, $this->options->qc_static_cache_post_types)) return; $this->core->singular->make_cache($post_ID, $post->post_type); if ($this->options->qc_static_cache_post_type_archive) $this->core->post_type_archive->make_cache($post->post_type); if ($this->options->qc_static_cache_homepage) $this->core->home->make_cache(); $taxonomies = get_object_taxonomies( $post->post_type ); $taxonomies = array_intersect($taxonomies, $this->options->qc_static_cache_taxonomies); if (!empty($taxonomies)) { $cron_terms_cache = get_option( $this->cron_cache, array() ); $changed = false; foreach ($taxonomies as $taxonomy) { $terms = wp_get_post_terms($post_ID, $taxonomy); if (!empty($terms)) { if (!isset($cron_terms_cache[$taxonomy])) $cron_terms_cache[$taxonomy] = array(); foreach ($terms as $term) { if (!in_array($term->term_id, $cron_terms_cache[$taxonomy])) { $cron_terms_cache[$taxonomy][] = $term->term_id; $changed = true; } } } } if ($changed) update_option( $this->cron_cache, $cron_terms_cache ); } } public function refreash_action() { $cron_terms_cache = get_option( $this->cron_cache, array() ); $changed = false; if (!empty($cron_terms_cache)) { foreach ($cron_terms_cache as $taxonomy => $terms) { if (in_array($taxonomy, $this->options->qc_static_cache_taxonomies) && !empty($terms)) { foreach ($terms as $index => $term_id) { $this->core->archive->make_cache($term_id, $taxonomy); unset($cron_terms_cache[$taxonomy][$index]); $changed = true; } } } if ($changed) update_option( $this->cron_cache, $cron_terms_cache ); } } } ?>